using UnityEngine;
namespace NakiLegend.Prototype {
 public sealed partial class NakiPrototype {
  private void ConfigureNewIceEnemy(Enemy e){if(e.kind==EnemyKind.FrostLens){e.boss=false;e.hp=e.maximum=44;e.radius=.35f;e.speed=0;e.iceArmor=0;e.affinity=e.attackElement=Element.Ice;e.soulEligible=false;e.body.sprite=BossPropSprite(0);e.root.transform.localScale=Vector3.one*.9f;return;}bool boss=e.kind==EnemyKind.FrostMirror||e.kind==EnemyKind.TideGuardian;e.boss=boss;e.radius=boss?.9f:.32f;e.affinity=e.attackElement=Element.Ice;e.hp=e.maximum=e.kind==EnemyKind.TideGuardian?1480:e.kind==EnemyKind.FrostMirror?1060:e.kind==EnemyKind.SnowCrab?85:64;e.speed=boss?1.2f:e.kind==EnemyKind.SnowMoth?1.6f:1.1f;e.iceArmor=boss?4:e.kind==EnemyKind.SnowCrab?1:0;e.nextAttack=clock+1.5f;e.soulEligible=!boss||e.kind==EnemyKind.FrostMirror;}
  private void UpdateNewIceEnemy(Enemy e,float dt){if(e.kind==EnemyKind.FrostLens){e.root.transform.position=e.position;e.body.sortingOrder=DepthAt(e.position.y);e.body.color=clock<e.hurtUntil?C("fff4d1"):C("a7edff");if(e.shadow!=null)e.shadow.transform.position=e.position;return;}Vector2 old=e.position,to=position-e.position;bool boss=e.boss;
   if(boss&&!e.secondPhase&&e.hp<e.maximum*.7f){e.secondPhase=true;e.recoveryUntil=clock+1.2f;e.windup=0;if(e.warning!=null)Destroy(e.warning);AddFloatingHit("寒潮涌动 · 注意连续弹幕",e.position+Vector2.up*2,C("b5efff"));if(e.kind==EnemyKind.FrostMirror)SpawnFrostMirrors(e);if(e.kind==EnemyKind.TideGuardian){BuildChapterActions();JourneyHint("回流绞盘已松动 · 靠近两侧按 F，可冲开寒潮");}}
   if(e.chargeUntil>0){if(clock<e.chargeUntil){Vector2 next=MoveEnemyCharge(e,e.attackDirection*(boss?7:4)*dt);if(IceNavigationLine(e.position,next,e.radius))e.position=next;else e.chargeUntil=clock;if(DistanceToSegment(position,old,e.position)<e.radius+.3f&&!ProjectilePathBlocked(e.position,position,.04f))TakeJourneyDamage(boss?2:1,Element.Ice);}else{e.chargeUntil=0;e.recoveryUntil=clock+1;}}
   else if(e.windup>0){e.windup-=dt;if(e.windup<=0){if(e.warning!=null)Destroy(e.warning);ResolveNewIceMove(e);}}
   else if(clock>=e.recoveryUntil){bool visible=!ProjectilePathBlocked(e.position,position,.14f);if(clock>=e.nextAttack&&visible&&to.magnitude<(boss?11:e.kind==EnemyKind.SnowCrab?2:7)){e.attackNumber++;e.attackDirection=to.sqrMagnitude>.01f?to.normalized:Vector2.down;e.strikePoint=position;e.windup=boss?1.05f:.8f;e.nextAttack=clock+e.windup+(boss?(e.secondPhase?.8f:1.25f):1.8f);e.warning=NewIceWarning(e);}else if(!visible||to.magnitude>(boss?4:e.kind==EnemyKind.SnowCrab?1.5f:4))MoveIcePursuit(e,e.speed*(clock<e.iceSlowUntil?.55f:1)*dt);}
   e.velocity=dt>0?(e.position-old)/dt:Vector2.zero;e.root.transform.position=e.position+Vector2.up*(e.kind==EnemyKind.SnowMoth?.16f+.05f*Mathf.Sin(clock*6):0);e.body.flipX=(e.windup>0?e.attackDirection:to).x<0;e.body.sortingOrder=DepthAt(e.position.y);e.body.color=clock<e.hurtUntil?C("ffe2d0"):e.kind==EnemyKind.TideGuardian&&clock<tideCoreUntil?C("c6ffe9"):Color.white;if(e.shadow!=null)e.shadow.transform.position=e.position;
  }
  private void IceFan(Enemy e,int count,float spacing,float speed,float offset=0){DensifyFan(ref count,ref spacing);for(int i=0;i<count;i++){Vector2 dir=Quaternion.Euler(0,0,offset+(i-(count-1)*.5f)*spacing)*e.attackDirection;int n=shots.Count;SpawnShot(e.position+dir*(e.radius+.2f),dir,true,null,e.position);if(shots.Count>n){var s=shots[shots.Count-1];s.emitter=e;s.element=Element.Ice;s.damage=e.boss?1.5f:1;s.speed=speed;s.life=3.2f;s.root.GetComponent<SpriteRenderer>().color=C(e.kind==EnemyKind.FrostLens?"f3ddff":"a4e8ff");}}}
  private void ResolveNewIceMove(Enemy e){e.recoveryUntil=clock+(e.boss?.75f:.65f);int move=e.attackNumber%3;if(e.kind==EnemyKind.FrostMirror&&e.secondPhase&&move!=1)QueueMirrorVolleys(e);
   if(e.kind==EnemyKind.SnowCrab){if(DistanceToSegment(position,e.position,e.position+e.attackDirection*2)<.55f&&!ProjectilePathBlocked(e.position,position,.03f))TakeJourneyDamage(1,Element.Ice);return;}
   if(e.kind==EnemyKind.SnowMoth){IceFan(e,3,18,3.5f);foreach(Shot s in shots)if(s.hostile&&Vector2.Distance(s.position,e.position)<3)s.direction=(s.direction+(Vector2)(Quaternion.Euler(0,0,90)*e.attackDirection)*.12f).normalized;return;}
   if(move==0){GameObject root=Draw("Active tidal impact",windRingSprite??disc,e.strikePoint,Vector2.one*2.5f,C("83cced"),-635);icePatches.Add(new IcePatch{at=e.strikePoint,root=root,expires=clock+1.2f,nextHit=clock});SkillSound("ice_ring","hit");IceFan(e,e.secondPhase?9:7,20,4.3f);}
   else if(move==1&&e.kind==EnemyKind.FrostMirror){e.chargeUntil=clock+.65f;IceFan(e,e.secondPhase?9:7,14,4);}
   else{IceFan(e,e.secondPhase?13:9,e.kind==EnemyKind.TideGuardian?23:13,e.secondPhase?4.7f:4.1f);if(e.kind==EnemyKind.TideGuardian)IceFan(e,e.secondPhase?8:5,32,3,16);}
  }
 }
}
